import React, { useMemo } from 'react';
import ReactFlow, { 
  Background, 
  Controls, 
  MiniMap,
  useNodesState,
  useEdgesState
} from 'reactflow';
import 'reactflow/dist/style.css';
import './ArchitectureDiagram.css';

const ArchitectureDiagram = ({ data }) => {
  const { nodes, edges } = useMemo(() => {
    if (!data || data.length === 0) {
      return { nodes: [], edges: [] };
    }

    const getNodeColor = (type) => {
      switch (type) {
        case 'DU_ONLINE':
          return 'linear-gradient(145deg, #2d5aa0, #1e3f72)'; // Blue for main services
        case 'DTO':
          return 'linear-gradient(145deg, #a02d5a, #721e3f)'; // Red for DTOs
        case 'LIB':
          return 'linear-gradient(145deg, #5aa02d, #3f721e)'; // Green for Libraries
        case 'TRX':
          return 'linear-gradient(145deg, #a0772d, #72551e)'; // Orange for Transactions
        case 'ARTIFACT': // Keep for backward compatibility
          return 'linear-gradient(145deg, #666, #444)';
        case 'SERVICE': // Keep for backward compatibility
          return 'linear-gradient(145deg, #666, #444)';
        case 'MODULE': // Keep for backward compatibility
          return 'linear-gradient(145deg, #666, #444)';
        default:
          return 'linear-gradient(145deg, #666, #444)';
      }
    };

    const getTooltipText = (unit) => {
      let tooltip = `${unit.name} (${unit.type})`;
      if (unit.uuaa) tooltip += `\\nUUAA: ${unit.uuaa}`;
      if (unit.code) tooltip += `\\nCode: ${unit.code}`;
      if (unit.className) tooltip += `\\nClass: ${unit.className}`;
      if (unit.description) tooltip += `\\nDescription: ${unit.description}`;
      tooltip += `\\nCreated: ${new Date(unit.createdAt).toLocaleDateString()}`;
      return tooltip;
    };

    // Create nodes from deployment units
    const generatedNodes = data.map((unit, index) => {
      const position = {
        x: (index % 3) * 300 + 100,
        y: Math.floor(index / 3) * 200 + 100
      };

      return {
        id: unit.id.toString(),
        type: 'default',
        position,
        data: {
          label: (
            <div className="deployment-unit-node" title={getTooltipText(unit)}>
              <div className="unit-header">
                <div className="unit-name">{unit.name}</div>
                <div className="unit-type">{unit.type}</div>
              </div>
              <div className="unit-folders">
                {(() => {
                  // Group component folders by type
                  const groupedFolders = {};
                  unit.componentFolders?.forEach(folder => {
                    const type = folder.type.toLowerCase();
                    if (!groupedFolders[type]) {
                      groupedFolders[type] = [];
                    }
                    if (folder.objectName) {
                      groupedFolders[type].push(folder);
                    }
                  });

                  // Show folder types based on deployment unit type
                  let folderTypes = [];
                  if (unit.type === 'DU_ONLINE') {
                    folderTypes = ['dto', 'library', 'transactions'];
                  } else if (unit.type === 'DU_LIB') {
                    folderTypes = ['parent'];
                  }
                  
                  return folderTypes.map(type => (
                    <div key={type} className={`folder ${type}`}>
                      <div className="folder-header">{type}</div>
                      {groupedFolders[type] && groupedFolders[type].map((folder, index) => (
                        <div key={`${folder.type}-${folder.id}-${index}`} className="nested-object">
                          <div className="object-name">{folder.objectName}</div>
                          {folder.className && (
                            <div className="object-class">{folder.className}</div>
                          )}
                        </div>
                      ))}
                    </div>
                  ));
                })()}
              </div>
              {/* Custom Tooltip */}
              <div className="custom-tooltip">
                <div className="tooltip-header">
                  <strong>{unit.name}</strong>
                  <span className="tooltip-type">{unit.type}</span>
                </div>
                <div className="tooltip-content">
                  {unit.uuaa && (
                    <div className="tooltip-field">
                      <strong>UUAA:</strong> {unit.uuaa}
                    </div>
                  )}
                  {unit.code && (
                    <div className="tooltip-field">
                      <strong>Code:</strong> {unit.code}
                    </div>
                  )}
                  {unit.className && (
                    <div className="tooltip-field">
                      <strong>Class:</strong> {unit.className}
                    </div>
                  )}
                  {unit.description && (
                    <div className="tooltip-field">
                      <strong>Description:</strong> {unit.description}
                    </div>
                  )}
                  <div className="tooltip-field">
                    <strong>Created:</strong> {new Date(unit.createdAt).toLocaleDateString()}
                  </div>
                  {unit.componentFolders && unit.componentFolders.length > 0 && (
                    <div className="tooltip-field">
                      <strong>Folders:</strong>
                      <div className="folder-details">
                        {unit.componentFolders.map(f => (
                          <div key={`${f.type}-${f.id}`} className="folder-detail">
                            <span className="folder-type">{f.type.toLowerCase()}</span>
                            {f.objectName && (
                              <span className="object-info">
                                : {f.objectName}
                                {f.className && ` (${f.className})`}
                                {f.objectDescription && ` - ${f.objectDescription}`}
                              </span>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )
        },
        style: {
          background: getNodeColor(unit.type),
          border: '2px solid #555',
          borderRadius: '8px',
          color: '#fff',
          fontSize: '12px',
          width: 180,
          padding: 0
        }
      };
    });

    // Create edges from dependencies
    const generatedEdges = [];
    data.forEach(unit => {
      if (unit.dependencyNames && unit.dependencyNames.length > 0) {
        unit.dependencyNames.forEach(depName => {
          const targetUnit = data.find(u => u.name === depName);
          if (targetUnit) {
            generatedEdges.push({
              id: `${unit.id}-${targetUnit.id}`,
              source: unit.id.toString(),
              target: targetUnit.id.toString(),
              type: 'smoothstep',
              style: {
                stroke: '#00ff00',
                strokeWidth: 2
              },
              markerEnd: {
                type: 'arrowclosed',
                color: '#00ff00'
              }
            });
          }
        });
      }
    });

    return { nodes: generatedNodes, edges: generatedEdges };
  }, [data]);

  const [flowNodes, setNodes, onNodesChange] = useNodesState(nodes);
  const [flowEdges, setEdges, onEdgesChange] = useEdgesState(edges);

  // Update nodes and edges when data changes
  React.useEffect(() => {
    setNodes(nodes);
    setEdges(edges);
  }, [nodes, edges, setNodes, setEdges]);

  return (
    <div className="architecture-diagram">
      <div className="diagram-header">
        <h3>Architecture Diagram</h3>
        <div className="legend">
          <div className="legend-item">
            <div className="legend-color du-online"></div>
            <span>DU-Online</span>
          </div>
          <div className="legend-item">
            <div className="legend-color dto"></div>
            <span>DTO</span>
          </div>
          <div className="legend-item">
            <div className="legend-color lib"></div>
            <span>Library</span>
          </div>
          <div className="legend-item">
            <div className="legend-color trx"></div>
            <span>Transaction</span>
          </div>
        </div>
      </div>
      
      <div className="diagram-content">
        {flowNodes.length === 0 ? (
          <div className="empty-diagram">
            <div className="empty-message">
              <h4>No deployment units created</h4>
              <p>Use the terminal to create banking components:</p>
              <code>apx init</code>
            </div>
          </div>
        ) : (
          <ReactFlow
            nodes={flowNodes}
            edges={flowEdges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            fitView
            attributionPosition="bottom-left"
          >
            <Background color="#333" gap={20} />
            <Controls />
            <MiniMap 
              nodeColor="#00ff00"
              maskColor="rgba(0, 0, 0, 0.6)"
              style={{ backgroundColor: '#1a1a1a' }}
            />
          </ReactFlow>
        )}
      </div>
    </div>
  );
};

export default ArchitectureDiagram;
